def normalize(text):
    """前後の空白を落とし、連続する空白を 1 個に潰した文字列を返す。"""
    return " ".join(text.split())

def truncate(text, limit):
    """text が limit 文字を超える場合は limit 文字に切り詰めて … を付けて返す。"""
    if len(text) <= limit:
        return text
    return text[:limit] + "…"

